import hashlib,json,pathlib
out=pathlib.Path('/out'); out.mkdir()
inputs={'schemaVersion':'{{workflow.parameters.schema-version}}','requestId':'{{workflow.parameters.request-id}}','requestedAt':'{{workflow.parameters.requested-at}}','projectRevision':'{{workflow.parameters.project-revision}}','infrastructureRevision':'{{workflow.parameters.infrastructure-revision}}','requestDigest':'{{workflow.parameters.request-digest}}','configurationDigest':'{{workflow.parameters.configuration-digest}}','fixtureDigest':'{{workflow.parameters.fixture-digest}}','evaluationPolicyDigest':'{{workflow.parameters.evaluation-policy-digest}}','candidateArtifactId':'{{workflow.parameters.candidate-artifact-id}}','candidateArtifactDigest':'{{workflow.parameters.candidate-artifact-digest}}','baseModelId':'{{workflow.parameters.base-model-id}}','baseModelDigest':'{{workflow.parameters.base-model-digest}}'}
def payload(v): return (json.dumps(v,sort_keys=True,separators=(',',':'))+'\n').encode()
def digest(v): return 'sha256:'+hashlib.sha256(payload(v)).hexdigest()
identity={'digest':digest(inputs),'inputs':inputs}
decision={'contentIdentityDigest':identity['digest'],'failedClauses':['synthetic_fixture_forces_rejection'],'outcome':'rejected','schemaVersion':'v1','selectedArtifactDigest':inputs['baseModelDigest'],'selectedModelId':inputs['baseModelId']}
release={'artifactDigest':inputs['baseModelDigest'],'modelId':inputs['baseModelId'],'schemaVersion':'v1','selection':'base'}
